   159:  async function handleLogBp(metric: HealthMetric) {
   160:    setHealthMetrics((prev) => [...prev, metric]);
   161:    const recordedAt = demoNow ?? new Date().toISOString();
   162:    let decision: AgentDecision;
   163:    try {
   164:      const result = await api.healthMetric({
   165:        systolic: metric.systolic,
   166:        diastolic: metric.diastolic,
   167:        note: metric.note,
   168:        recordedAt,
   169:      });
   170:      decision = result.decision;
   171:      setLatestDecision(decision);
   172:      await refreshToday();
   173:    } catch {
   174:      // Offline fallback: call the rules engine directly so the beat still works.
   175:      const updatedMetrics = [...healthMetrics, metric];
   176:      const input = buildAgentInputFromState({
   177:        now: recordedAt,
