   188:      reportApiProblem("health-metric request failed");
   189:    }
   190:    setBpLogged(true);
   191:    // Emergency and see-GP moments stay calm: no playful toast.
   192:    if (decision.decision !== "emergency_995" && decision.decision !== "see_gp_soon") {
   193:      notify(t("toast.bpLogged", { name: dogName }));
   194:    }
   195:  }
