   203:  async function handleWalkState(walking: boolean, simulated?: WalkCompletion) {
   204:    if (walking) {
   205:      setWalkStartedAt(new Date().toISOString());
   206:      return;
   207:    }
   208:    if (!walkStartedAt && !simulated) return;
   209:    const startedAt = walkStartedAt ?? new Date().toISOString();
   210:    const finishedAt = new Date().toISOString();
   211:    setWalkStartedAt(null);
   212:    setDizzy(false);
   213:    try {
   214:      const result = await api.walkSession({
   215:        startedAt,
